excels.excel:

EXPORT WITH SHEET="员工培训档案登记", HEADER=true,
    MAPPING={"a":"工号","b":"姓名","c":"部门","d":"培训课程","e":"培训日期","f":"学时","g":"考核成绩","h":"是否通过"},
    FORMAT={"e":"yyyy-MM-dd","f":"0","g":"0"},
    FORMULAS={
        F7:'SUM(F2:F6)',G7:'AVERAGE(G2:G6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        G4:{color:red,bold:true}
    }
